import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Política de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy.md","filePath":"es/guide/privacy.md","lastUpdated":1793173149000}`),a={name:`es/guide/privacy.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="politica-de-privacidad" tabindex="-1">Política de privacidad <a class="header-anchor" href="#politica-de-privacidad" aria-label="Permalink to “Política de privacidad”">​</a></h1><p>Sudoku es una aplicación que funciona sin conexión en primer lugar, con funciones en la nube opcionales. Esta página explica qué datos recopila la app (si es que recopila alguno) y cómo se utilizan.</p><h2 id="nucleo-sin-conexion-no-se-recopilan-datos-para-jugar" tabindex="-1">Núcleo sin conexión: no se recopilan datos para jugar <a class="header-anchor" href="#nucleo-sin-conexion-no-se-recopilan-datos-para-jugar" aria-label="Permalink to “Núcleo sin conexión: no se recopilan datos para jugar”">​</a></h2><ul><li>El juego de puzles principal funciona por completo sin conexión. No se necesita acceso a la red para jugar.</li><li>Todos los datos de juego (ajustes, estado de la partida, notas a lápiz y estadísticas) se almacenan localmente en tu dispositivo.</li><li>No hay anuncios, ni analíticas, ni SDK de rastreo de terceros.</li></ul><h2 id="funciones-en-la-nube-opcionales" tabindex="-1">Funciones en la nube opcionales <a class="header-anchor" href="#funciones-en-la-nube-opcionales" aria-label="Permalink to “Funciones en la nube opcionales”">​</a></h2><h3 id="sincronizacion-con-icloud-cloudkit" tabindex="-1">Sincronización con iCloud (CloudKit) <a class="header-anchor" href="#sincronizacion-con-icloud-cloudkit" aria-label="Permalink to “Sincronización con iCloud (CloudKit)”">​</a></h3><p>Cuando inicias sesión en iCloud y activas la sincronización:</p><ul><li>Las partidas guardadas, las estadísticas, los ajustes y el progreso del desafío diario se sincronizan con tu <strong>cuenta personal de iCloud</strong> mediante el servicio CloudKit de Apple.</li><li>Apple cifra los datos en tránsito y en reposo con su infraestructura.</li><li>Solo tú puedes acceder a los datos sincronizados con tu Apple ID.</li><li>Esta función es totalmente opcional: la app funciona perfectamente sin ella.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Cuando inicias sesión en Game Center:</p><ul><li>Las puntuaciones de las clasificaciones (mejores tiempos de finalización por dificultad) pueden compartirse en clasificaciones públicas.</li><li>El progreso de los logros lo registra el servicio Game Center de Apple.</li><li>Tu nombre visible de Game Center es visible para otros jugadores en las clasificaciones.</li><li>Esta función es totalmente opcional.</li></ul><h2 id="el-unico-otro-acceso-a-la-red-«mas-apps»" tabindex="-1">El único otro acceso a la red: «Más apps» <a class="header-anchor" href="#el-unico-otro-acceso-a-la-red-«mas-apps»" aria-label="Permalink to “El único otro acceso a la red: «Más apps»”">​</a></h2><p>La única función de red no basada en la nube es una sección opcional de <strong>«Más apps»</strong> en Ajustes, que obtiene una lista de apps hermanas de nuestros servidores. Esta función:</p><ul><li>Solo se activa cuando vas a Ajustes → Más apps.</li><li>Obtiene una lista ligera con nombres y enlaces de apps; no se envía ni se almacena ningún dato personal.</li><li>Puedes ignorarla por completo y no afecta en absoluto a la jugabilidad.</li></ul><h2 id="que-no-recopilamos" tabindex="-1">Qué no recopilamos <a class="header-anchor" href="#que-no-recopilamos" aria-label="Permalink to “Qué no recopilamos”">​</a></h2><ul><li>No recopilamos información personal, archivos, imágenes ni historial de navegación.</li><li>No enviamos ningún dato de juego a servidores externos (salvo lo descrito más arriba para iCloud y Game Center).</li><li>No incluimos SDK de analíticas ni de publicidad de terceros.</li><li>No utilizamos servicios de informes de fallos ni de telemetría.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to “Permisos”">​</a></h2><p>Sudoku requiere permisos mínimos:</p><ul><li><strong>iCloud</strong> (opcional): para sincronizar los datos de juego entre dispositivos mediante CloudKit.</li><li><strong>Game Center</strong> (opcional): para clasificaciones y logros.</li><li><strong>Red</strong> (opcional): para la sincronización con iCloud, Game Center y «Más apps».</li></ul><p>No se solicitan permisos de ubicación, contactos, cámara, micrófono ni otros permisos sensibles para la privacidad.</p><h2 id="conservacion-de-datos" tabindex="-1">Conservación de datos <a class="header-anchor" href="#conservacion-de-datos" aria-label="Permalink to “Conservación de datos”">​</a></h2><ul><li>Los datos locales permanecen en tu dispositivo hasta que desinstalas o restableces la app.</li><li>Los datos sincronizados con iCloud siguen las políticas de conservación de datos de iCloud de Apple.</li><li>Los datos de Game Center siguen las políticas de Game Center de Apple.</li></ul><h2 id="solicitudes-de-privacidad" tabindex="-1">Solicitudes de privacidad <a class="header-anchor" href="#solicitudes-de-privacidad" aria-label="Permalink to “Solicitudes de privacidad”">​</a></h2><p>Como Sudoku guarda todos los datos localmente (y, opcionalmente, en tu iCloud personal), no hay datos en servidores que nosotros controlemos o a los que accedamos. Para borrar todos los datos de la app:</p><ul><li><strong>Desinstala la app</strong> de tu dispositivo o dispositivos.</li><li><strong>Restablece los datos de iCloud</strong>: en Ajustes → [Tu nombre] → iCloud → Gestionar almacenamiento de la cuenta → Sudoku → Eliminar datos.</li><li><strong>Restablecimiento local en Mac</strong>: consulta la guía de solución de problemas para las instrucciones de eliminación del contenedor.</li></ul><h2 id="privacidad-de-los-menores" tabindex="-1">Privacidad de los menores <a class="header-anchor" href="#privacidad-de-los-menores" aria-label="Permalink to “Privacidad de los menores”">​</a></h2><p>Sudoku no recopila activamente información personal de nadie, incluidos los menores. La app no requiere cuentas, funciones de chat ni redes sociales.</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to “Contacto”">​</a></h2><p>Si tienes preguntas sobre privacidad, abre un issue en el repositorio del proyecto (<a href="https://github.com/sudoku-pro/sudoku-site" target="_blank" rel="noreferrer">https://github.com/sudoku-pro/sudoku-site</a>) o escríbenos a <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};